from pathlib import Path
from PIL import Image
import hashlib,json
p=Path(__file__).resolve().parent;r=p.parents[1]
rows=json.loads((p/'contact-v13-prompt-index.json').read_bytes())['poses']
crop=[80,96,176,192];rect=[88,116,151,161]
standing=r/'character/james-west-master-carry-v1/local-v3-carry-pose.png'
for i,neighbors,problem in [(3,(2,4),'The case bottom sits below both neighbours and its panel reads too tall. Raise the lower edge and connected fingertips about3 native pixels; preserve neighbours\' compact panel height and small latch scale. Do not simply enlarge or broaden the whole box.'),(30,(29,31),'The case is LOWER than both neighbours, not higher. Raise the complete rigid case and connected gloves about2 native pixels. The rejected downward correction is not a reference.')]:
 name=f'walk{i:02d}-contact-v14';base=p/rows[i]['source'];files=[base,standing,Path(__file__),p/'package_key.py',p/'package_pose.py',p/'contact-v13-prompt-index.json']
 refs=[]
 for f,suffix in [(base,'target'),(standing,'standing-reference')]+[(p/rows[j]['source'],f'neighbour-{j:02d}') for j in neighbors]:
  target=p/f'{name}-{suffix}.png';Image.open(f).convert('RGBA').crop(crop).resize((384,384),Image.Resampling.LANCZOS).save(target);refs.append(target);files.extend([f,target])
 prompt=f'''Edit image1 ONLY: fixed James West carrying phase{i}, original96x96 native crop enlarged4x. Images3/4 show the immediate previous/next poses at exactly the same camera, framing and physical scale. Make the case and both hands form a coherent intermediate carry pose between THESE TWO neighbours. {problem} Image2 is a provisional standing carry reference for the physical rigid graphite case, not an instruction to copy its legs, stance or equipment. Keep exactly one flat-front graphite rectangular case with modest bevel/depth, four SMALL dull silver corner latches, and neutral matte finish. Keep panel width and height comparable to images3/4, avoid the large square chrome blocks seen in rejected edits. Far glove grips LEFT edge, near glove naturally wraps RIGHT edge, visible fingertips attached to existing wrist/cuff. Preserve camera and native material density. Keep image1 costume/head/legs/hips/shoulder and torso outside necessary case/wrist correction unchanged. No extra case bob, large black occlusion patch, missing far glove, stretched hand, box clipping into abdomen, cuff size change, purple tint, brightening or stylization. Retain original high anatomical-left belt meter and its current natural glove occlusion; do not expose/duplicate hardware, add yellow flecks or a near-side wrench/metal loop. Anatomical-right wrench stays far side body-occluded. Do not copy image2's tool pixels or change body proportions. Return full square image1 crop on genuinely transparent background, correcting ONLY connected case/grips and necessary local wrist/forearm contact.'''
 pf=p/f'{name}-prompt.txt';pf.write_text(prompt+'\n',encoding='utf-8');files.append(pf)
 (p/f'{name}-inputs.json').write_text(json.dumps({'preCallSha256':{f.relative_to(r).as_posix():hashlib.sha256(f.read_bytes()).hexdigest() for f in set(files)},'crop':crop,'admissionRegion':rect,'baseFile':base.name,'references':[f.relative_to(r).as_posix() for f in refs],'scope':'Second bounded case/contact attempt; correct actual neighbour direction, preserve original head/legs and native density.'},indent=2)+'\n')
print('Two corrected-direction case/grip inputs frozen.')
